package main

import (
	"encoding/json"
	"sync"
	"time"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// gossipBody is the payload we use to pass values between nodes.
type gossipBody struct {
	Type     string `json:"type"`
	Messages []int  `json:"messages"`
}

// broadcastBody is a client broadcast request.
type broadcastBody struct {
	Type    string `json:"type"`
	Message int    `json:"message"`
}

func main() {
	n := maelstrom.NewNode()

	var mu sync.Mutex
	seen := make(map[int]struct{})
	// peers we push values to; falls back to every other node
	var peers []string

	// merge records values and returns the ones that were new to us.
	merge := func(vals []int) []int {
		mu.Lock()
		defer mu.Unlock()
		var added []int
		for _, v := range vals {
			if _, ok := seen[v]; !ok {
				seen[v] = struct{}{}
				added = append(added, v)
			}
		}
		return added
	}

	snapshot := func() []int {
		mu.Lock()
		defer mu.Unlock()
		out := make([]int, 0, len(seen))
		for v := range seen {
			out = append(out, v)
		}
		return out
	}

	// targets returns the current set of peers, defaulting to the whole
	// cluster when we have not been given a topology yet.
	targets := func() []string {
		mu.Lock()
		out := append([]string(nil), peers...)
		mu.Unlock()
		if len(out) > 0 {
			return out
		}
		for _, id := range n.NodeIDs() {
			if id != n.ID() {
				out = append(out, id)
			}
		}
		return out
	}

	// push sends the given values to every peer, ignoring empty batches.
	push := func(vals []int) {
		if len(vals) == 0 {
			return
		}
		for _, t := range targets() {
			if t == n.ID() {
				continue
			}
			n.Send(t, gossipBody{Type: "gossip", Messages: vals})
		}
	}

	n.Handle("gossip", func(msg maelstrom.Message) error {
		var b gossipBody
		if err := json.Unmarshal(msg.Body, &b); err != nil {
			return err
		}
		added := merge(b.Messages)
		// Push anything new onwards so values keep spreading even if the
		// immediate sender only knew part of the cluster.
		go push(added)
		return nil
	})

	n.Handle("broadcast", func(msg maelstrom.Message) error {
		var b broadcastBody
		if err := json.Unmarshal(msg.Body, &b); err != nil {
			return err
		}
		added := merge([]int{b.Message})
		if err := n.Reply(msg, map[string]any{"type": "broadcast_ok"}); err != nil {
			return err
		}
		go push(added)
		return nil
	})

	n.Handle("read", func(msg maelstrom.Message) error {
		return n.Reply(msg, map[string]any{
			"type":     "read_ok",
			"messages": snapshot(),
		})
	})

	n.Handle("topology", func(msg maelstrom.Message) error {
		var b struct {
			Topology map[string][]string `json:"topology"`
		}
		if err := json.Unmarshal(msg.Body, &b); err != nil {
			return err
		}
		var next []string
		if t, ok := b.Topology[n.ID()]; ok && len(t) > 0 {
			for _, id := range t {
				if id != n.ID() {
					next = append(next, id)
				}
			}
		}
		mu.Lock()
		peers = next
		mu.Unlock()
		return n.Reply(msg, map[string]any{"type": "topology_ok"})
	})

	// Periodic anti-entropy: shove the full set at every peer so anything
	// that got lost (or arrived while a peer was still starting) converges.
	go func() {
		for range time.Tick(400 * time.Millisecond) {
			go push(snapshot())
		}
	}()

	if err := n.Run(); err != nil {
		panic(err)
	}
}

